      if (a[pos] !== line.slice(1)) fail(`line ${pos + 1} does not match`);
      pos++;
    }

    for (let i = cursor; i < oldIndex; i++) out.push(a[i]);
    pos = oldIndex;
    for (const line of lines) {
      if (line[0] === '+') {
        out.push(line.slice(1));
      } else {
        if (line[0] === ' ') out.push(a[pos]);
        pos++;
      }
    }
    cursor = pos;
    shift += newLines - oldLines;
  }

  for (let i = cursor; i < a.length; i++) out.push(a[i]);
  return out;
}

