'use strict';

/**
 * Return an edit script of { op: 'equal' | 'delete' | 'insert', line: string }.
 * a and b are arrays of strings; lines are compared by exact string equality.
 * Reading equal/delete entries reconstructs a; equal/insert reconstructs b.
 * Equal entries must form a longest common subsequence: the number of deletes
 * plus inserts equals a.length + b.length - 2 * LCS(a, b).
 * Results must be deterministic. In every maximal region without an equal
 * entry, all deletes precede all inserts. No particular LCS is otherwise required.
 * Neither input may be mutated. Empty arrays and repeated/empty strings work.
 * Small changes to 20,000-line inputs must run well under a second: use a Myers
 * O((N + M) * D) algorithm (linear when D is zero), not an O(N * M) LCS table.
 * Here N/M are input lengths and D is the minimal number of inserts + deletes.
 */
function diffLines(a, b) {
  assertLines(a, 'a');
  assertLines(b, 'b');

  // Intern lines as small integers so the inner loops compare numbers.
  // A Map (not a plain object) keeps keys like '__proto__' safe.
  const ids = new Map();
  const intern = (lines) => {
    const out = new Int32Array(lines.length);
    for (let i = 0; i < lines.length; i++) {
      let id = ids.get(lines[i]);
      if (id === undefined) {
        id = ids.size;
        ids.set(lines[i], id);
      }
      out[i] = id;
    }
    return out;
  };
  const A = intern(a);
  const B = intern(b);

  const raw = [];
  const emitEqual = (lo, hi) => {
    for (let i = lo; i < hi; i++) raw.push({ op: 'equal', line: a[i] });
  };
  const emitDelete = (lo, hi) => {
    for (let i = lo; i < hi; i++) raw.push({ op: 'delete', line: a[i] });
  };
  const emitInsert = (lo, hi) => {
    for (let i = lo; i < hi; i++) raw.push({ op: 'insert', line: b[i] });
  };

  // Linear-space Myers: trim the common prefix/suffix, find the middle snake,
  // and recurse on both halves. Each split point lies on an optimal path, so
  // the concatenated script is minimal. Recursion depth is ~log(D) because
  // the middle snake halves the remaining edit distance.
  const compare = (aLo, aHi, bLo, bHi) => {
    const prefixStart = aLo;
    while (aLo < aHi && bLo < bHi && A[aLo] === B[bLo]) {
      aLo++;
      bLo++;
    }
    emitEqual(prefixStart, aLo);

    const suffixEnd = aHi;
    while (aHi > aLo && bHi > bLo && A[aHi - 1] === B[bHi - 1]) {
      aHi--;
      bHi--;
    }

    if (aLo === aHi) {
      emitInsert(bLo, bHi);
    } else if (bLo === bHi) {
      emitDelete(aLo, aHi);
    } else {
      const [x, y] = middleSnake(A, aLo, aHi, B, bLo, bHi);
      compare(aLo, x, bLo, y);
      compare(x, aHi, y, bHi);
    }

    emitEqual(aHi, suffixEnd);
  };
  compare(0, A.length, 0, B.length);

  return deletesBeforeInserts(raw);
}

/**
 * Find a split point (absolute indices into A and B) lying on a shortest edit
 * path between A[aLo..aHi) and B[bLo..bHi). Both ranges must be non-empty and
 * must differ in their first and last elements, so the split point is strictly
 * inside the edit graph and recursion always makes progress.
 */
function middleSnake(A, aLo, aHi, B, bLo, bHi) {
  const n = aHi - aLo;
  const m = bHi - bLo;
  const maxD = Math.ceil((n + m) / 2);
  const offset = maxD;
  const size = 2 * maxD + 2;
  // vf[k]: furthest x on diagonal k (x - y) going forward from (0, 0).
  const maxD = Math.ceil((n + m) / 2);
  // Diagonals reach ±(maxD + 1) through the k ± 1 neighbour lookups.
  const offset = maxD + 1;
  const size = 2 * maxD + 3;
  const vb = new Int32Array(size).fill(-1);
  vf[offset + 1] = 0;
  vb[offset + 1] = 0;
  const delta = n - m;
  // With an odd delta the paths first meet during a forward step, otherwise
  // during a backward step.
  const front = (delta & 1) !== 0;
  // Diagonals that ran off the grid are skipped in later rounds.
  let kfStart = 0;
  let kfEnd = 0;
  let kbStart = 0;
  let kbEnd = 0;

  for (let d = 0; d < maxD; d++) {
    for (let k = -d + kfStart; k <= d - kfEnd; k += 2) {
      const ko = offset + k;
      let x = k === -d || (k !== d && vf[ko - 1] < vf[ko + 1]) ? vf[ko + 1] : vf[ko - 1] + 1;
  for (let d = 0; d <= maxD; d++) {
      while (x < n && y < m && A[aLo + x] === B[bLo + y]) {
        x++;
        y++;
      }
      vf[ko] = x;
      if (x > n) {
        kfEnd += 2;
      } else if (y > m) {
        kfStart += 2;
      } else if (front) {
        const kbo = offset + delta - k;
        if (kbo >= 0 && kbo < size && vb[kbo] !== -1 && x >= n - vb[kbo]) {
          return [aLo + x, bLo + y];
        }
      }
    }

    for (let k = -d + kbStart; k <= d - kbEnd; k += 2) {
      const ko = offset + k;
      let x = k === -d || (k !== d && vb[ko - 1] < vb[ko + 1]) ? vb[ko + 1] : vb[ko - 1] + 1;
      let y = x - k;
      while (x < n && y < m && A[aHi - 1 - x] === B[bHi - 1 - y]) {
        x++;
        y++;
      }
      vb[ko] = x;
      if (x > n) {
        kbEnd += 2;
      } else if (y > m) {
        kbStart += 2;
      } else if (!front) {
        const kfo = offset + delta - k;
        if (kfo >= 0 && kfo < size && vf[kfo] !== -1) {
          const fx = vf[kfo];
          const fy = fx - (kfo - offset);
          if (fx >= n - x) return [aLo + fx, bLo + fy];
        }
      }
    }
  }

  // The forward and backward searches always meet within ceil((n + m) / 2)
  // rounds; reaching this line means the algorithm above is broken.
  throw new Error('internal error: middle snake not found');
}

/**
 * Within every maximal run of non-equal entries, move deletes before inserts.
 * The relative order of deletes (and of inserts) is unchanged, so the script
 * still reconstructs both inputs.
 */
function deletesBeforeInserts(ops) {
  const out = [];
  let i = 0;
  while (i < ops.length) {
    if (ops[i].op === 'equal') {
      out.push(ops[i++]);
      continue;
    }
    const inserts = [];
    while (i < ops.length && ops[i].op !== 'equal') {
      if (ops[i].op === 'delete') out.push(ops[i]);
      else inserts.push(ops[i]);
      i++;
    }
    for (const op of inserts) out.push(op);
  }
  return out;
}

/**
 * Return unified hunks: [{ oldStart, oldLines, newStart, newLines, lines }].
 * context is a nonnegative integer, default 3. Hunk lines are original strings
 * prefixed with ' ' (equal), '-' (delete), or '+' (insert); remove exactly one
 * prefix to recover a line, even when the original starts with a prefix itself.
 * oldLines counts context + deletes; newLines counts context + inserts.
 * Include up to context unchanged lines before/after each changed region.
 * Merge regions if the intervening unchanged gap is <= 2 * context (their
 * context would touch or overlap). Do not duplicate context in merged hunks.
 * Starts are 1-based, except a zero-line range names the line BEFORE the range:
 * oldLines === 0 uses the preceding old line number (0 for insertion at top),
 * and newLines === 0 uses the preceding new line number (0 for deletion at top).
 * Coordinates refer to the complete original a and result b, not a local hunk.
 * Identical inputs return []. Use diffLines' minimality and deletion ordering.
 * Neither input may be mutated. Inputs follow the diffLines contract.
 */
function unifiedHunks(a, b, { context = 3 } = {}) {
  if (!Number.isInteger(context) || context < 0) {
    throw new RangeError('context must be a nonnegative integer');
  }
  const ops = diffLines(a, b);

  // Old/new line positions (0-based) immediately before each op.
  const oldPos = new Array(ops.length + 1);
  const newPos = new Array(ops.length + 1);
  oldPos[0] = 0;
  newPos[0] = 0;
  for (let i = 0; i < ops.length; i++) {
    oldPos[i + 1] = oldPos[i] + (ops[i].op === 'insert' ? 0 : 1);
    newPos[i + 1] = newPos[i] + (ops[i].op === 'delete' ? 0 : 1);
  }

  // Maximal changed regions as [start, end) op index ranges.
  const regions = [];
  for (let i = 0; i < ops.length; ) {
    if (ops[i].op === 'equal') {
      i++;
      continue;
    }
    const start = i;
    while (i < ops.length && ops[i].op !== 'equal') i++;
    regions.push([start, i]);
  }

  const hunks = [];
  let r = 0;
  while (r < regions.length) {
    let last = r;
    while (last + 1 < regions.length && regions[last + 1][0] - regions[last][1] <= 2 * context) {
      last++;
    }
    const from = Math.max(0, regions[r][0] - context);
    const to = Math.min(ops.length, regions[last][1] + context);

    const lines = [];
    for (let i = from; i < to; i++) {
      const { op, line } = ops[i];
      lines.push((op === 'equal' ? ' ' : op === 'delete' ? '-' : '+') + line);
    }
    const oldLines = oldPos[to] - oldPos[from];
    const newLines = newPos[to] - newPos[from];
    hunks.push({
      oldStart: oldLines === 0 ? oldPos[from] : oldPos[from] + 1,
      oldLines,
      newStart: newLines === 0 ? newPos[from] : newPos[from] + 1,
      newLines,
      lines,
    });
    r = last + 1;
  }
  return hunks;
}

/**
 * Return a new array by applying unified hunks to a, without mutating either.
 * Hunk old coordinates refer to the original a: apply in the given order,
 * tracking offsets caused by earlier insertions/deletions. Hunks must be
 * nonoverlapping and ordered; their counts and new coordinates must agree with
 * their lines. Verify every ' ' and '-' line exactly against a before consuming
