'use strict';

/**
 * Return an edit script of { op: 'equal' | 'delete' | 'insert', line: string }.
 * a and b are arrays of strings; lines are compared by exact string equality.
 * Reading equal/delete entries reconstructs a; equal/insert reconstructs b.
 * Equal entries must form a longest common subsequence: the number of deletes
 * plus inserts equals a.length + b.length - 2 * LCS(a, b).
 * Results must be deterministic. In every maximal region without an equal
 * entry, all deletes precede all inserts. No particular LCS is otherwise required.
 * Neither input may be mutated. Empty arrays and repeated/empty strings work.
 * Small changes to 20,000-line inputs must run well under a second: use a Myers
 * O((N + M) * D) algorithm (linear when D is zero), not an O(N * M) LCS table.
 * Here N/M are input lengths and D is the minimal number of inserts + deletes.
 */
function diffLines(a, b) {
  assertLines(a, 'a');
  assertLines(b, 'b');

  // Intern lines as small integers so the inner loops compare numbers.
  // A Map (not a plain object) keeps keys like '__proto__' safe.
  const ids = new Map();
  const intern = (lines) => {
    const out = new Int32Array(lines.length);
    for (let i = 0; i < lines.length; i++) {
      let id = ids.get(lines[i]);
      if (id === undefined) {
        id = ids.size;
        ids.set(lines[i], id);
      }
      out[i] = id;
    }
    return out;
  };
  const A = intern(a);
  const B = intern(b);

  const raw = [];
  const emitEqual = (lo, hi) => {
    for (let i = lo; i < hi; i++) raw.push({ op: 'equal', line: a[i] });
  };
  const emitDelete = (lo, hi) => {
    for (let i = lo; i < hi; i++) raw.push({ op: 'delete', line: a[i] });
  };
  const emitInsert = (lo, hi) => {
    for (let i = lo; i < hi; i++) raw.push({ op: 'insert', line: b[i] });
  };

  // Linear-space Myers: trim the common prefix/suffix, find the middle snake,
  // and recurse on both halves. Each split point lies on an optimal path, so
  // the concatenated script is minimal. Recursion depth is ~log(D) because
  // the middle snake halves the remaining edit distance.
  const compare = (aLo, aHi, bLo, bHi) => {
    const prefixStart = aLo;
    while (aLo < aHi && bLo < bHi && A[aLo] === B[bLo]) {
      aLo++;
      bLo++;
    }
    emitEqual(prefixStart, aLo);

    const suffixEnd = aHi;
    while (aHi > aLo && bHi > bLo && A[aHi - 1] === B[bHi - 1]) {
      aHi--;
      bHi--;
    }

    if (aLo === aHi) {
      emitInsert(bLo, bHi);
    } else if (bLo === bHi) {
      emitDelete(aLo, aHi);
    } else {
      const [x, y] = middleSnake(A, aLo, aHi, B, bLo, bHi);
      compare(aLo, x, bLo, y);
      compare(x, aHi, y, bHi);
    }

    emitEqual(aHi, suffixEnd);
  };
  compare(0, A.length, 0, B.length);

  return deletesBeforeInserts(raw);
}

/**
 * Find a split point (absolute indices into A and B) lying on a shortest edit
 * path between A[aLo..aHi) and B[bLo..bHi). Both ranges must be non-empty and
 * must differ in their first and last elements, so the split point is strictly
 * inside the edit graph and recursion always makes progress.
 */
function middleSnake(A, aLo, aHi, B, bLo, bHi) {
  const n = aHi - aLo;
  const m = bHi - bLo;
  const maxD = Math.ceil((n + m) / 2);
  // Diagonals reach ±(maxD + 1) through the k ± 1 neighbour lookups.
  const offset = maxD + 1;
  const size = 2 * maxD + 3;
  // vf[k]: furthest x on diagonal k (x - y) going forward from (0, 0).
  // vb[k]: furthest distance travelled backwards from (n, m) on reversed
  // diagonal k, i.e. x measured from the end.
  const vf = new Int32Array(size).fill(-1);
  const vb = new Int32Array(size).fill(-1);
  vf[offset + 1] = 0;
  vb[offset + 1] = 0;
  const delta = n - m;
  // With an odd delta the paths first meet during a forward step, otherwise
  // during a backward step.
  const front = (delta & 1) !== 0;
  // Diagonals that ran off the grid are skipped in later rounds.
  let kfStart = 0;
  let kfEnd = 0;
  let kbStart = 0;
  let kbEnd = 0;

  for (let d = 0; d <= maxD; d++) {
    for (let k = -d + kfStart; k <= d - kfEnd; k += 2) {
      const ko = offset + k;
      let x = k === -d || (k !== d && vf[ko - 1] < vf[ko + 1]) ? vf[ko + 1] : vf[ko - 1] + 1;
      let y = x - k;
      while (x < n && y < m && A[aLo + x] === B[bLo + y]) {
        x++;
        y++;
      }
      vf[ko] = x;
      if (x > n) {
        kfEnd += 2;
      } else if (y > m) {
        kfStart += 2;
      } else if (front) {
        const kbo = offset + delta - k;
        if (kbo >= 0 && kbo < size && vb[kbo] !== -1 && x >= n - vb[kbo]) {
          return [aLo + x, bLo + y];
        }
      }
    }

    for (let k = -d + kbStart; k <= d - kbEnd; k += 2) {
      const ko = offset + k;
      let x = k === -d || (k !== d && vb[ko - 1] < vb[ko + 1]) ? vb[ko + 1] : vb[ko - 1] + 1;
      let y = x - k;
      while (x < n && y < m && A[aHi - 1 - x] === B[bHi - 1 - y]) {
        x++;
        y++;
      }
      vb[ko] = x;
      if (x > n) {
        kbEnd += 2;
      } else if (y > m) {
        kbStart += 2;
      } else if (!front) {
        const kfo = offset + delta - k;
