}

/**
 * Within every maximal run of non-equal entries, move deletes before inserts.
 * The relative order of deletes (and of inserts) is unchanged, so the script
 * still reconstructs both inputs.
 */
function deletesBeforeInserts(ops) {
  const out = [];
  let i = 0;
  while (i < ops.length) {
    if (ops[i].op === 'equal') {
      out.push(ops[i++]);
      continue;
    }
    const inserts = [];
    while (i < ops.length && ops[i].op !== 'equal') {
      if (ops[i].op === 'delete') out.push(ops[i]);
      else inserts.push(ops[i]);
      i++;
    }
    for (const op of inserts) out.push(op);
  }
