 * containing 'hunk <index> does not apply', where index is zero-based.
 */
function applyHunks(a, hunks) {
  assertLines(a, 'a');
  if (!Array.isArray(hunks)) throw new TypeError('hunks must be an array');

  const out = [];
  let cursor = 0; // next unconsumed index in a
  let shift = 0; // (new length - old length) contributed by earlier hunks

  for (let h = 0; h < hunks.length; h++) {
    const fail = (reason) => {
      throw new Error(`hunk ${h} does not apply: ${reason}`);
    };
    const hunk = hunks[h];
    if (hunk === null || typeof hunk !== 'object') fail('not an object');
    const { oldStart, oldLines, newStart, newLines, lines } = hunk;
    for (const [name, value] of [['oldStart', oldStart], ['oldLines', oldLines],
      ['newStart', newStart], ['newLines', newLines]]) {
      if (!Number.isInteger(value) || value < 0) fail(`${name} must be a nonnegative integer`);
    }
    if (!Array.isArray(lines) || lines.length === 0) fail('lines must be a non-empty array');

    let olds = 0;
    let news = 0;
    for (const line of lines) {
      if (typeof line !== 'string' || line.length === 0) fail('hunk line without prefix');
      const prefix = line[0];
      if (prefix === ' ') {
        olds++;
        news++;
      } else if (prefix === '-') {
        olds++;
      } else if (prefix === '+') {
        news++;
      } else {
        fail(`unknown line prefix ${JSON.stringify(prefix)}`);
      }
    }
    if (olds !== oldLines) fail(`oldLines is ${oldLines} but lines contain ${olds}`);
    if (news !== newLines) fail(`newLines is ${newLines} but lines contain ${news}`);

    // A zero-line range names the line before it; otherwise starts are 1-based.
    if (oldLines > 0 && oldStart === 0) fail('oldStart must be 1-based');
    if (newLines > 0 && newStart === 0) fail('newStart must be 1-based');
    const oldIndex = oldLines === 0 ? oldStart : oldStart - 1;
    const newIndex = newLines === 0 ? newStart : newStart - 1;
    if (oldIndex < cursor) fail('overlaps or precedes an earlier hunk');
    if (oldIndex + oldLines > a.length) fail('extends past the end of the input');
    if (newIndex !== oldIndex + shift) {
      fail(`newStart ${newStart} disagrees with expected ${oldIndex + shift + (newLines === 0 ? 0 : 1)}`);
    }

    // Verify the whole hunk before producing any output from it.
    let pos = oldIndex;
    for (const line of lines) {
      if (line[0] === '+') continue;
      if (a[pos] !== line.slice(1)) fail(`line ${pos + 1} does not match`);
      pos++;
    }

    for (let i = cursor; i < oldIndex; i++) out.push(a[i]);
    pos = oldIndex;
    for (const line of lines) {
      if (line[0] === '+') {
        out.push(line.slice(1));
      } else {
        if (line[0] === ' ') out.push(a[pos]);
        pos++;
      }
    }
    cursor = pos;
    shift += newLines - oldLines;
  }

  for (let i = cursor; i < a.length; i++) out.push(a[i]);
  return out;
}

function assertLines(lines, name) {
  if (!Array.isArray(lines)) throw new TypeError(`${name} must be an array of strings`);
  for (let i = 0; i < lines.length; i++) {
    if (typeof lines[i] !== 'string') throw new TypeError(`${name}[${i}] must be a string`);
  }
}

module.exports = { diffLines, unifiedHunks, applyHunks };

